import React, { useState } from 'react';

export default function ManageTeachers() {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [subject, setSubject] = useState('');

  const addTeacher = async () => {
    const res = await fetch('http://localhost:8081/add-teacher', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, phone, email, subject })
    });
    const data = await res.json();
    if (data.status === 'Success') {
      alert("ටීචර්ව සාර්ථකව එකතු කළා!");
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      <h2>Manage Teachers</h2>
      <input placeholder="නම" onChange={(e) => setName(e.target.value)} />
      <input placeholder="ෆෝන් නම්බර්" onChange={(e) => setPhone(e.target.value)} />
      <input placeholder="Email" onChange={(e) => setEmail(e.target.value)} />
      <input placeholder="විෂය" onChange={(e) => setSubject(e.target.value)} />
      <button onClick={addTeacher}>Add Teacher</button>
    </div>
  );
}
